<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {route} from '../router';import {runs} from '../stores/runs';import {reviews} from '../stores/reviews';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {fixed,pct} from '../utils/format';import {analysisMethodLabels} from '../constants/enums';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import CalibrationMetrics from '../components/CalibrationMetrics.vue';import AgreementPlot from '../components/AgreementPlot.vue';import PairTable from '../components/PairTable.vue';const selected=ref(route.value.query.get('run')||'demo-run'),action=ref('对照量程与重复测量依据复核比例偏倚，检查界限外配对；BA界限不是CI，不据此直接宣称探头可互换。'),notice=ref('');watch(()=>route.value.query.get('run'),v=>{selected.value=v||'demo-run'});const {error,busy,act}=useTask();let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();timer=setInterval(runs.load,2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result);const method=computed(()=>result.value?.analysis_method||'difference');const isLog=computed(()=>method.value==='log_ratio');function runLabel(id:string){if(id==='demo-run')return '三量程基线·原差值';if(id==='demo-log-run')return '三量程基线·对数比值';return id.slice(0,8)}function submit(){act(async()=>{await reviews.create({run_id:selected.value,action:action.value});notice.value='偏倚复核已提交，等待管理员批准。'})}</script><template><PageHeading index="04 / 运行底稿" title="校准关系，与一致性分布一并复核。" note="两图都来自同一批持久化Python结果。Deming不是单侧OLS，一致性界限不是偏倚置信区间。"/><div class="result-toolbar"><label>运行记录<select v-model="selected"><option v-for="r in runs.items.value" :key="r.id" :value="r.id">{{runLabel(r.id)}} · {{r.status}}</option></select></label><StatusPill v-if="run" :status="run.status"/></div><Notice :message="error||runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="独立worker正在计算Deming与一致性分析，结果每两秒刷新。"/><template v-if="run?.status==='completed'&&result"><p class="method-banner">分析方式：<b>{{analysisMethodLabels[method]}}</b> · 单位 {{result.unit}} · <span v-if="isLog">容差为相对偏差百分比含义</span><span v-else>容差为同读数单位绝对差含义</span></p><CalibrationMetrics :result="result"/><div class="result-plots"><section><h2>Deming校准散点（原读数）</h2><AgreementPlot :result="result" mode="deming"/></section><section><h2 v-if="isLog">对数比值 Bland–Altman 图</h2><h2 v-else>Bland–Altman 差值图</h2><AgreementPlot :result="result" :mode="isLog?'log_ba':'ba'"/></section></div><div class="result-columns"><section><h2>界限外配对与读数预览</h2><PairTable :rows="result.points.filter((p:any)=>p.outside_loa).concat(result.points.filter((p:any)=>!p.outside_loa).slice(0,12))" :mode="method"/><form v-if="canWrite()" class="review-form" @submit.prevent="submit"><label>偏倚复核说明<textarea v-model="action" rows="4" required minlength="8"></textarea></label><button :disabled="busy">提交偏倚复核</button><p class="success" v-if="notice">{{notice}}</p></form></section><aside class="field-note" v-if="isLog"><p class="eyebrow">METHOD & LIMITS</p><h3>对数比值口径 ln(Y/X)</h3><p v-if="result.log_agreement.proportional.estimable">ln(Y/X)={{fixed(result.log_agreement.proportional.intercept,4)}} + {{fixed(result.log_agreement.proportional.slope,4)}} × ln√(XY)</p><p v-else>{{result.log_agreement.proportional.reason}}</p><p>有效 {{result.n}} 组，比值界限外 {{result.log_agreement.outside_loa}} 组；相对容差 ±{{result.log_agreement.relative_tolerance_pct}}% 外 {{result.outside_tolerance}} 组。</p><p>几何均比 {{fixed(result.log_agreement.geometric_mean_ratio,4)}} 倍，界限 {{fixed(result.log_agreement.ratio_loa_low,4)}} ~ {{fixed(result.log_agreement.ratio_loa_high,4)}} 倍（指数还原，无量纲）。</p><p>y方向残差RMSE {{fixed(result.deming.residual_rmse_y)}} {{result.unit}}，Deming始终基于原{{result.unit}}读数，仅作拟合残差摘要。</p><p class="note-rule">{{result.log_agreement.limits_note}} 含零或负值时 ln(Y/X) 无定义，该运行已明确失败而非跳过变换。</p></aside><aside class="field-note" v-else><p class="eyebrow">METHOD & LIMITS</p><h3>比例偏倚回归</h3><p v-if="result.agreement.proportional.estimable">差值={{fixed(result.agreement.proportional.intercept)}} + {{fixed(result.agreement.proportional.slope,4)}} × 均值</p><p v-else>{{result.agreement.proportional.reason}}</p><p>有效 {{result.n}} 组，界限外 {{result.agreement.outside_loa}} 组；讨论容差 ±{{result.tolerance}} {{result.unit}} 外 {{result.outside_tolerance}} 组。</p><p>y方向残差RMSE {{fixed(result.deming.residual_rmse_y)}} {{result.unit}}，仅作拟合残差摘要。</p><p class="note-rule">{{result.agreement.limits_note}} 若差值随均值变化或方差不齐，应先讨论量程/变换口径。</p></aside></div></template></template>
